def compute_angle_statistics_and_correlation(
    ei_results: Dict[str, Any],
) -> Dict[str, Any]:
    return ei_processor.compute_angle_statistics_and_correlation(ei_results)

def assemble_weighted_stack(
    ei_volumes: Sequence[ArrayLike], weights, verbose: bool = True
) -> np.ndarray:
    return ei_processor.assemble_weighted_stack(ei_volumes, weights, verbose=verbose)

def compute_ei_gradient_and_summary(
    ei_volumes, angles_array, weights=None, verbose=True
):
    return ei_processor.compute_ei_gradient_and_summary(
        ei_volumes, angles_array, weights=weights, verbose=verbose
    )

def compare_ei_angles(ei_results, facies_depth, slice_inline=75):
    return ei_processor.compare_ei_angles(
        ei_results, facies_depth, slice_inline=slice_inline
    )

def impedance_to_seismogram_depth(
    impedance: np.ndarray,
    grid_dz: float,
    f_peak: float = 30.0,
    dt_equiv_vp: float = 2500.0,
    mode: str = "same",
):
    return seismic_operator.impedance_to_seismogram_depth(
        impedance, grid_dz, f_peak=f_peak, dt_equiv_vp=dt_equiv_vp, mode=mode
    )

def convolve_reflectivity_with_wavelet(
    reflectivity_cube: np.ndarray, wavelet: np.ndarray, mode: str = "same"
) -> np.ndarray:
    return seismic_operator.convolve_reflectivity_with_wavelet(
        reflectivity_cube, wavelet, mode=mode
    )

def register_backend(name: str, impl: ResamplerBackend) -> None:
    # delegate to facade proxy for easier testing/mocking
    return backends_registry.register_backend(name, impl)

def compute_one_way_time(
    grid_spec: GridSpec, vp_trace: np.ndarray | Quantity
) -> np.ndarray:
    return get_resampler(grid_spec).compute_one_way_time(vp_trace)

def compute_one_way_times(
    grid_spec: GridSpec, vp_arr: np.ndarray | Quantity
) -> np.ndarray:
    return get_resampler(grid_spec).compute_one_way_times(vp_arr)

def depth_to_time_cube(
    grid_spec: GridSpec,
    data_depth: np.ndarray | Quantity,
    vp_depth: np.ndarray | Quantity,
    target_dt: Optional[float] = None,
    target_nt: Optional[int] = None,
    plan: ResamplePlan | None = None,
) -> tuple:
    return get_resampler(grid_spec).depth_to_time_cube(
        data_depth, vp_depth, target_dt=target_dt, target_nt=target_nt, plan=plan
    )

def time_to_depth_cube(
    grid_spec: GridSpec,
    seismogram_time: np.ndarray | Quantity,
    vp_depth: np.ndarray | Quantity,
    plan: ResamplePlan | None = None,
) -> np.ndarray | Quantity:
    return get_resampler(grid_spec).time_to_depth_cube(
        seismogram_time, vp_depth, plan=plan
    )

def plot_facies_only(
    ax,
    facies_slice,
    title,
    k_scale=1.0,
    k_label="K",
    k_unit="",
):
    return facies_overlay.plot_facies_only(
        ax, facies_slice, title, k_scale=k_scale, k_label=k_label, k_unit=k_unit
    )

def apply_wavelet_to_cube(
    refl_cube: np.ndarray,
    wavelet: np.ndarray,
    mode: str = "same",
    progress_every: Optional[int] = 30,
    prefix: str = "",
) -> np.ndarray:
    return _default_processor.apply_wavelet_to_cube(
        refl_cube, wavelet, mode=mode, progress_every=progress_every, prefix=prefix
    )

def impedance_to_seismogram(
    impedance, dt, f_peak=30, progress_every: Optional[int] = 30, prefix: str = ""
):
    return _default_processor.impedance_to_seismogram(
        impedance, dt, f_peak=f_peak, progress_every=progress_every, prefix=prefix
    )

def impedance_to_seismogram_depth(
    impedance, dz, f_peak=30, progress_every: Optional[int] = 30, prefix: str = ""
):
    return _default_processor.impedance_to_seismogram_depth(
        impedance, dz, f_peak=f_peak, progress_every=progress_every, prefix=prefix
    )

def create_figure_grid(
    figsize=(12, 8), nrows=1, ncols=1, gridspec_kw=None, constrained_layout=True
):
    return plot_helper.create_figure_grid(
        figsize=figsize,
        nrows=nrows,
        ncols=ncols,
        gridspec_kw=gridspec_kw,
        constrained_layout=constrained_layout,
    )
